            from_version: components["schemas"]["LockVersion"] | null;
            /** @description The solution lock after the job (the same as `from_version` after a rollback of the job). */
            to_version: components["schemas"]["LockVersion"] | null;
            /** @description The file in `state/locks/` that holds the lock before the job. `null` when the lock did not change. */
            from_lock: components["schemas"]["LockId"] | null;
            /** @description For a rollback, the file that it installed. Else `null`. */
            to_lock: components["schemas"]["LockId"] | null;
            /** @description For `plug-change`, the plug. */
            plug_id: components["schemas"]["PlugId"] | null;
            /** @description The checkpoint of the job. `null` when the job took none. */
            checkpoint: components["schemas"]["UpdateCheckpoint"] | null;
